<?php require __DIR__.'/../lib/bootstrap.php';require __DIR__.'/../lib/layout.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$names=[];$opts=[];foreach(['vi','en','zh'] as $lang){$names[$lang]=trim($_POST['display_name_'.$lang]??'');$lines=preg_split('/\r\n|\r|\n/',trim($_POST['options_'.$lang]??''));$opts[$lang]=array_values(array_filter(array_map('trim',$lines),fn($v)=>$v!==''));}$baseName=$names['vi']?:($names['en']?:$names['zh']);$baseOpts=$opts['vi']?:($opts['en']?:$opts['zh']);if($id&&$baseName&&$baseOpts){db()->prepare('UPDATE option_profiles SET display_name=?,display_name_vi=?,display_name_en=?,display_name_zh=?,options_json=?,options_json_vi=?,options_json_en=?,options_json_zh=? WHERE id=?')->execute([$baseName,$names['vi']?:null,$names['en']?:null,$names['zh']?:null,json_encode($baseOpts,JSON_UNESCAPED_UNICODE),$opts['vi']?json_encode($opts['vi'],JSON_UNESCAPED_UNICODE):null,$opts['en']?json_encode($opts['en'],JSON_UNESCAPED_UNICODE):null,$opts['zh']?json_encode($opts['zh'],JSON_UNESCAPED_UNICODE):null,$id]);}redirect('profiles.php');}
$rows=db()->query("SELECT * FROM option_profiles ORDER BY FIELD(profile_type,'ice','sugar'),code")->fetchAll();admin_header(t('global_options'));?>
<div class="alert info"><?=e(t('global_options_info'))?> <?=e(t('language_fields_help'))?></div><div class="profile-grid"><?php foreach($rows as $r):$vi=json_decode($r['options_json_vi']?:$r['options_json'],true)?:[];$en=json_decode($r['options_json_en']?:'[]',true)?:[];$zh=json_decode($r['options_json_zh']?:'[]',true)?:[];?><form method="post" class="panel profile-card"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><div class="profile-code"><span><?=$r['profile_type']==='ice'?e(t('ice')):e(t('sugar'))?></span><b><?=e($r['code'])?></b></div><div class="multilang-box"><label><?=e(t('name_vi'))?><input name="display_name_vi" value="<?=e($r['display_name_vi']?:$r['display_name'])?>" required></label><label><?=e(t('options_vi'))?><textarea name="options_vi" rows="5" required><?=e(implode("\n",$vi))?></textarea></label><label><?=e(t('name_en'))?><input name="display_name_en" value="<?=e($r['display_name_en']??'')?>"></label><label><?=e(t('options_en'))?><textarea name="options_en" rows="5"><?=e(implode("\n",$en))?></textarea></label><label><?=e(t('name_zh'))?><input name="display_name_zh" value="<?=e($r['display_name_zh']??'')?>"></label><label><?=e(t('options_zh'))?><textarea name="options_zh" rows="5"><?=e(implode("\n",$zh))?></textarea></label></div><button class="btn primary block"><?=e(t('save'))?></button></form><?php endforeach;?></div>
